   "java": "import java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int l = sc.nextInt(), r = sc.nextInt();\n        boolean[] comp = new boolean[r + 1];\n        comp[0] = true; if (r >= 1) comp[1] = true;\n        for (int p = 2; (long) p * p <= r; p++) if (!comp[p]) for (int m = p * p; m <= r; m += p) comp[m] = true;\n        StringBuilder sb = new StringBuilder();\n        for (int x = l; x <= r; x++) if (!comp[x]) { if (sb.length() > 0) sb.append(' '); sb.append(x); }\n        System.out.println(sb.length() > 0 ? sb : \"None\");\n    }\n}\n",
