  "topic": "Math · GCD",
  "kind": "pyq",
  "statement": "Two buses leave a depot every A and every B minutes. Print the GCD of A and B, then the LCM (the minutes until both leave together again), separated by a space.",
  "input_format": "One line with two integers A and B.",
  "output_format": "GCD and LCM separated by a space.",
