  "statement": "Remove every repeated character from the word, keeping only the first occurrence of each, in order.",
  "input_format": "One line: a word (letters and digits).",
  "output_format": "The word with repeats removed.",
  "constraints": [
   "1 ≤ length ≤ 10^5"
  ],
