  "statement": "Make the first and the last letter of every word upper case, and every other letter lower case. Words are separated by single spaces and contain letters only.",
  "input_format": "One line: the sentence.",
  "output_format": "The changed sentence.",
  "constraints": [
   "1 ≤ length ≤ 10^5"
  ],
  "samples": [
   {
    "input": "welcome to tcs nqt",
    "output": "WelcomE TO TcS NqT"
   },
   {
    "input": "a bb",
    "output": "A BB",
    "explain": "A one-letter word just becomes upper case."
   },
   {
    "input": "HELLO",
    "output": "HellO"
   }
  ],
  "hints": [
   "Handle one word at a time: lower-case it, then upper-case index 0 and index len − 1."
  ],
  "approach": "Split into words; for each, lower-case everything, then upper-case the first and last characters. Join with spaces.",
  "complexity": "O(L) time, O(L) space",
  "solutions": {
   "cpp": "#include <bits/stdc++.h>\nusing namespace std;\nint main() {\n    string line, w; getline(cin, line);\n    stringstream ss(line); bool first = true;\n    while (ss >> w) {\n        for (auto &c : w) c = tolower(c);\n        w[0] = toupper(w[0]); w.back() = toupper(w.back());\n        if (!first) cout << ' ';\n        cout << w; first = false;\n    }\n    cout << endl;\n}\n",
   "java": "import java.io.*;\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        String[] ws = new BufferedReader(new InputStreamReader(System.in)).readLine().trim().split(\" \");\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < ws.length; i++) {\n            char[] w = ws[i].toLowerCase().toCharArray();\n            w[0] = Character.toUpperCase(w[0]);\n            w[w.length - 1] = Character.toUpperCase(w[w.length - 1]);\n            if (i > 0) sb.append(' ');\n            sb.append(w);\n        }\n        System.out.println(sb);\n    }\n}\n",
   "python": "out = []\nfor w in input().split():\n    w = w.lower()\n    out.append(w.upper() if len(w) == 1 else w[0].upper() + w[1:-1] + w[-1].upper())\nprint(\" \".join(out))\n"
  },
