  "hints": [
   "Use one boolean flag per rule, set them in a single pass, then combine."
  ],
  "approach": "One pass sets flags for upper, lower, digit, special and space. The password is valid when length ≥ 8, the first four flags are set and there is no space.",
  "complexity": "O(L) time, O(1) space",
  "solutions": {
   "cpp": "#include <bits/stdc++.h>\nusing namespace std;\nint main() {\n    string s; getline(cin, s);\n    bool up = false, lo = false, dg = false, sp = false, space = false;\n    for (char c : s) {\n        if (c >= 'A' && c <= 'Z') up = true;\n        else if (c >= 'a' && c <= 'z') lo = true;\n        else if (c >= '0' && c <= '9') dg = true;\n        else if (string(\"!@#$%^&*\").find(c) != string::npos) sp = true;\n        else if (c == ' ') space = true;\n    }\n    cout << (s.size() >= 8 && up && lo && dg && sp && !space ? \"Valid\" : \"Invalid\") << endl;\n}\n",
   "java": "import java.io.*;\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        String s = new BufferedReader(new InputStreamReader(System.in)).readLine();\n        boolean up = false, lo = false, dg = false, sp = false, space = false;\n        for (char c : s.toCharArray()) {\n            if (c >= 'A' && c <= 'Z') up = true;\n            else if (c >= 'a' && c <= 'z') lo = true;\n            else if (c >= '0' && c <= '9') dg = true;\n            else if (\"!@#$%^&*\".indexOf(c) >= 0) sp = true;\n            else if (c == ' ') space = true;\n        }\n        System.out.println(s.length() >= 8 && up && lo && dg && sp && !space ? \"Valid\" : \"Invalid\");\n    }\n}\n",
   "python": "s = input()\nok = (len(s) >= 8 and any(c.isupper() for c in s) and any(c.islower() for c in s)\n      and any(c.isdigit() for c in s) and any(c in \"!@#$%^&*\" for c in s) and \" \" not in s)\nprint(\"Valid\" if ok else \"Invalid\")\n"
  },
