  "hints": [
   "x XOR x = 0 and x XOR 0 = x. XOR everything together."
  ],
  "approach": "XOR all values: pairs cancel to 0, and what remains is the odd-count value. No extra memory needed.",
  "complexity": "O(N) time, O(1) space",
  "solutions": {
   "cpp": "#include <bits/stdc++.h>\nusing namespace std;\nint main() {\n    int n; cin >> n; long long x = 0, v;\n    for (int i = 0; i < n; i++) { cin >> v; x ^= v; }\n    cout << x << endl;\n}\n",
   "java": "import java.io.*;\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));\n        st.nextToken(); int n = (int) st.nval; long x = 0;\n        for (int i = 0; i < n; i++) { st.nextToken(); x ^= (long) st.nval; }\n        System.out.println(x);\n    }\n}\n",
   "python": "import sys\nfrom functools import reduce\nfrom operator import xor\nd = sys.stdin.read().split()\nprint(reduce(xor, map(int, d[1:1 + int(d[0])])))\n"
  },
