  "id": "tcs-p02",
  "title": "Handshakes at the Reunion",
  "level": 5,
  "difficulty": "easy",
  "topic": "Scenario · combinatorics",
  "kind": "pyq",
  "statement": "At a reunion, every person shakes hands with every other person exactly once. Given the number of people N, print the total number of handshakes.",
  "input_format": "One line with an integer N.",
  "output_format": "The number of handshakes.",
  "constraints": [
   "0 ≤ N ≤ 10^9"
  ],
  "samples": [
   {
    "input": "3",
    "output": "3",
    "explain": "A-B, A-C, B-C"
   },
   {
    "input": "1",
    "output": "0"
   },
   {
    "input": "10",
    "output": "45"
   }
  ],
  "hints": [
   "Each pair shakes once: choose 2 out of N."
  ],
  "approach": "The answer is N(N − 1) / 2, the number of pairs. It needs 64 bits for N up to 10^9.",
  "complexity": "O(1)",
  "solutions": {
   "cpp": "#include <bits/stdc++.h>\nusing namespace std;\nint main() { long long n; cin >> n; cout << (n > 1 ? n * (n - 1) / 2 : 0) << endl; }\n",
   "java": "import java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        long n = new Scanner(System.in).nextLong();\n        System.out.println(n > 1 ? n * (n - 1) / 2 : 0);\n    }\n}\n",
   "python": "n = int(input().strip())\nprint(n * (n - 1) // 2 if n > 1 else 0)\n"
  },
