  "hints": [
   "A subarray (i, j] has sum prefix[j] − prefix[i]. You need pairs where prefix[i] = prefix[j] − K.",
   "Count earlier prefix sums in a hash map as you go. Start the map with {0: 1}."
  ],
  "approach": "Walk the array keeping the running prefix sum and a map from prefix value to how many times it occurred. At each step add count[prefix − K] to the answer, then record prefix. Two nested loops would be O(N²) and time out; a sliding window fails with negative numbers.",
  "complexity": "O(N) time, O(N) space",
  "solutions": {
   "cpp": "#include <bits/stdc++.h>\nusing namespace std;\nint main() {\n    int n; long long k; cin >> n >> k;\n    unordered_map<long long, long long> seen; seen[0] = 1;\n    long long s = 0, ans = 0;\n    for (int i = 0; i < n; i++) { long long x; cin >> x; s += x; auto it = seen.find(s - k); if (it != seen.end()) ans += it->second; seen[s]++; }\n    cout << ans << endl;\n}\n",
   "java": "import java.util.*;\nimport java.io.*;\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        StringTokenizer st = new StringTokenizer(br.readLine());\n        int n = Integer.parseInt(st.nextToken()); long k = Long.parseLong(st.nextToken());\n        st = new StringTokenizer(br.readLine());\n        HashMap<Long, Integer> seen = new HashMap<>(); seen.put(0L, 1);\n        long s = 0, ans = 0;\n        for (int i = 0; i < n; i++) {\n            s += Long.parseLong(st.nextToken());\n            ans += seen.getOrDefault(s - k, 0);\n            seen.merge(s, 1, Integer::sum);\n        }\n        System.out.println(ans);\n    }\n}\n",
   "python": "import sys\nd = sys.stdin.read().split()\nn, k = int(d[0]), int(d[1])\nseen = {0: 1}; s = 0; ans = 0\nfor x in map(int, d[2:2 + n]):\n    s += x\n    ans += seen.get(s - k, 0)\n    seen[s] = seen.get(s, 0) + 1\nprint(ans)\n"
  },
