  "title": "Book Exchange (Derangements)",
  "level": 6,
  "difficulty": "hard",
  "topic": "DP · recurrence",
  "kind": "pyq",
  "statement": "N friends each bring one book and put them in a pile. Each friend then takes one book so that nobody gets their own. In how many ways can this happen? Print the answer modulo 1,000,000,007.",
  "input_format": "One line with an integer N.",
  "output_format": "The number of ways modulo 10^9 + 7.",
  "constraints": [
   "1 ≤ N ≤ 10^6"
  ],
