  "title": "Minimum Coins",
  "level": 6,
  "difficulty": "medium",
  "topic": "DP · unbounded knapsack",
  "kind": "practice",
  "statement": "You have unlimited coins of N denominations. Find the fewest coins that add up to exactly A. Print -1 if A cannot be made.",
  "input_format": "First line: N and A. Second line: N distinct denominations.",
  "output_format": "The minimum number of coins, or -1.",
  "constraints": [
   "1 ≤ N ≤ 100",
   "1 ≤ denomination ≤ 10^4",
   "0 ≤ A ≤ 10^4"
  ],
